def parsear_duracion(s):
    horas, minutos = s.split('h')
    return int(horas) * 60 + int(minutos)

def es_palindromo(s):
    s = ''.join(char.lower() for char in s if char.isalnum())
    return s == s[::-1]

def aplanar(lista):
    result = []
    for item in lista:
        if isinstance(item, list):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

def buscar(lista, x):
    izquierda = 0
    derecha = len(lista) - 1

    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2

        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1

    return -1

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)  # Manejo de casos donde n es mayor que el largo de la lista
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if n < 1 or n > 3999:
        return "Error: El número debe estar entre 1 y 3999."

    romanos = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    resultado = ''
    for valor, simbolo in romanos:
        while n >= valor:
            resultado += simbolo
            n -= valor

    return resultado

def desde_romano(s):
    romanos = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    prev = 0
    for c in s:
        value = romanos[c]
        if value > prev:
            total += value - 2 * prev
        else:
            total += value
        prev = value
    return total

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = lista[0]
    max_longitud = 1
    current_elemento = lista[0]
    current_longitud = 1

    for elemento in lista[1:]:
        if elemento == current_elemento:
            current_longitud += 1
        else:
            if current_longitud > max_longitud:
                max_elemento = current_elemento
                max_longitud = current_longitud
            current_elemento = elemento
            current_longitud = 1

    if current_longitud > max_longitud:
        max_elemento = current_elemento
        max_longitud = current_longitud

    return (max_elemento, max_longitud)

def primos(n):
    if n < 2:
        return []
    primos = []
    for i in range(2, n + 1):
        if all(i % j != 0 for j in range(2, int(i**0.5) + 1)):
            primos.append(i)
    return primos

def mcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    intervalos.sort()  # Ordena los intervalos por inicio
    resultado = [intervalos[0]]  # Inicializa el resultado con el primer intervalo

    for inicio, fin in intervalos[1:]:
        if inicio <= resultado[-1][1]:  # Si el inicio del nuevo intervalo es menor o igual al final del último intervalo fusionado
            resultado[-1][1] = max(resultado[-1][1], fin)  # Fusiona los intervalos
        else:
            resultado.append((inicio, fin))  # Si no, agrega el nuevo intervalo al resultado

    return resultado

def comprimir(s):
    if len(s) <= 1:
        return s
    compressed = ""
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            compressed += s[i-1] + str(count)
            count = 1
    compressed += s[-1] + str(count)
    return compressed if len(compressed) < len(s) else s

def balanceado(s):
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack.pop() != char:
                return False
    return not stack

def transpuesta(m):
    if not m:
        return []
    return [[m[j][i] for j in range(len(m))] for i in range(len(m[0]))]

def raiz_digital(n):
    while n >= 10:
        n = sum(int(digit) for digit in str(n))
    return n

def n_esimo_mayor(lista, n):
    if n <= 0 or n > len(set(lista)):
        return None
    return sorted(set(lista), reverse=True)[n-1]

def formatear_bytes(n):
    unidades = ['B', 'KB', 'MB', 'GB']
    for i in range(len(unidades)):
        if n >= 1024:
            n /= 1024
        else:
            return f"{n:.1f} {unidades[i]}"
    return "0 B"
